import sys

def read_ints():
    return list(map(int, sys.stdin.readline().strip().split()))

def find_sequence(N, B):
    # Initialize the sequence with the smallest possible values
    A = [0] * N
    for i in range(N):
        for j in range(N):
            if i != j:
                A[i] = min(A[i], B[i][j])
    return A

def update_matrix(B, p, new_values):
    for i in range(len(B)):
        B[i][p] = B[p][i] = new_values[i]
    return B

def main():
    N, Q = read_ints()
    B = [read_ints() for _ in range(N)]

    # Find the initial sequence
    initial_sequence = find_sequence(N, B)
